// Worker in front of the static site. Routes /api/track (recipe-picked /
// timer-started / brew-completed events, see README's "Recipe stats"
// section) and /api/stats (public read of those counts via the Analytics
// Engine SQL API); everything else falls through to the static assets.

const VALID_EVENTS = new Set(["picked", "started", "completed"]);
const VALID_RECIPES = new Set(["foursix", "v60-hoffmann"]);
// Anonymous per-browser id generated by app.js (crypto.randomUUID()).
const VISITOR_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const BOT_UA_RE =
  /bot|crawl|spider|slurp|headless|lighthouse|phantom|puppeteer|playwright|selenium|curl|wget|python|httpclient|scrapy|axios|node-fetch|go-http/i;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname === "/api/track") {
      return handleTrack(request, env);
    }
    if (url.pathname === "/api/stats") {
      return handleStats(request, env);
    }
    // run_worker_first sends every /api/* here. Unknown ones (bots probing
    // /api/.env etc.) get a plain 404 instead of the static-asset fallback.
    if (url.pathname.startsWith("/api/")) {
      return new Response("Not found", { status: 404 });
    }
    return env.ASSETS.fetch(request);
  },
};

// Analytics Engine can't be read from inside a Worker, so query Cloudflare's
// SQL API over HTTP. Needs ACCOUNT_ID (var in wrangler.jsonc) and the
// CF_API_TOKEN secret (Account Analytics: Read).
async function querySql(env, sql) {
  const res = await fetch(
    "https://api.cloudflare.com/client/v4/accounts/" + env.ACCOUNT_ID + "/analytics_engine/sql",
    { method: "POST", headers: { Authorization: "Bearer " + env.CF_API_TOKEN }, body: sql }
  );
  if (!res.ok) throw new Error("sql " + res.status);
  const { data } = await res.json();
  return data || [];
}

async function handleStats(request, env) {
  if (request.method !== "GET") {
    return new Response("Method not allowed", { status: 405 });
  }
  if (!env.ACCOUNT_ID || !env.CF_API_TOKEN) {
    return Response.json({ error: "Stats not configured" }, { status: 503 });
  }

  // blob3 = visitor id. Rows without one predate visitor tracking and bot
  // filtering, so they are excluded to keep every number comparable.
  let rows, total;
  try {
    [rows, total] = await Promise.all([
      querySql(
        env,
        "SELECT blob2 AS recipe, blob1 AS event, SUM(double1) AS count, " +
          "COUNT(DISTINCT blob3) AS visitors " +
          "FROM pourover_stats WHERE blob3 != '' " +
          "GROUP BY blob2, blob1"
      ),
      querySql(
        env,
        "SELECT COUNT(DISTINCT blob3) AS visitors FROM pourover_stats WHERE blob3 != ''"
      ),
    ]);
  } catch (e) {
    return Response.json({ error: "Stats unavailable" }, { status: 502 });
  }

  const recipes = {};
  for (const row of rows) {
    if (!VALID_RECIPES.has(row.recipe) || !VALID_EVENTS.has(row.event)) continue;
    recipes[row.recipe] = recipes[row.recipe] || {
      picked: 0, started: 0, completed: 0, visitors: {},
    };
    recipes[row.recipe][row.event] = Number(row.count);
    recipes[row.recipe].visitors[row.event] = Number(row.visitors);
  }

  return Response.json(
    { recipes, uniqueVisitors: Number((total[0] || {}).visitors || 0) },
    { headers: { "Cache-Control": "public, max-age=60" } }
  );
}

// Best-effort bot filter. Real browsers send same-origin Sec-Fetch-Site/Origin
// with sendBeacon; scripts and scanners usually don't, and many identify
// themselves in the UA. Not a guarantee against a determined scraper.
function looksLikeBot(request, url) {
  const ua = request.headers.get("user-agent") || "";
  if (!ua || BOT_UA_RE.test(ua)) return true;
  if (request.cf && request.cf.verifiedBotCategory) return true;
  const site = request.headers.get("sec-fetch-site");
  if (site && site !== "same-origin") return true;
  const origin = request.headers.get("origin");
  if (origin && origin !== url.origin) return true;
  return false;
}

async function handleTrack(request, env) {
  if (request.method !== "POST") {
    return new Response("Method not allowed", { status: 405 });
  }

  let body;
  try {
    body = await request.json();
  } catch (e) {
    return new Response("Bad request", { status: 400 });
  }

  const { event, recipe, visitor } = body || {};
  if (!VALID_EVENTS.has(event) || !VALID_RECIPES.has(recipe) || !VISITOR_RE.test(visitor || "")) {
    return new Response("Bad request", { status: 400 });
  }

  // Bots get the same 204 as everyone else but are not recorded.
  if (looksLikeBot(request, new URL(request.url))) {
    return new Response(null, { status: 204 });
  }

  // Fire-and-forget, per Analytics Engine's API — no await, no error thrown.
  env.STATS.writeDataPoint({ blobs: [event, recipe, visitor.toLowerCase()], doubles: [1] });

  return new Response(null, { status: 204 });
}
